function canaryGate(canary, control, opts) {
  var minSamples = opts.minSamples, threshold = opts.threshold;
  if (canary.requests < minSamples) return 'ABSTAIN (only ' + canary.requests + ' canary requests, need ' + minSamples + ')';
  var canaryRate = canary.errors / canary.requests;   // inside the slice
  var controlRate = control.errors / control.requests;
  var increase = canaryRate - controlRate;
  if (increase > threshold) {
    return 'ROLLBACK (canary ' + (canaryRate * 100).toFixed(1) + '% vs control ' + (controlRate * 100).toFixed(1) + '%)';
  }
  return 'PROMOTE (canary ' + (canaryRate * 100).toFixed(1) + '% vs control ' + (controlRate * 100).toFixed(1) + '%)';
}

var opts = { minSamples: 5000, threshold: 0.003 };
console.log('Too little data:');
console.log(canaryGate({ requests: 800, errors: 2 }, { requests: 95000, errors: 190 }, opts));
console.log('Healthy canary:');
console.log(canaryGate({ requests: 6000, errors: 12 }, { requests: 94000, errors: 188 }, opts));
console.log('Canary on fire (but only 5% of traffic):');
console.log(canaryGate({ requests: 6000, errors: 1800 }, { requests: 94000, errors: 188 }, opts));
